which python3 python; python3 - <<'EOF'
import os,re
root='/challenge/inhere'
for dirpath,_,files in os.walk(root):
    for fn in sorted(files):
        p=os.path.join(dirpath,fn)
        data=open(p,'rb').read()
        m=re.match(rb'record \d\d-\d\d\n',data)
        if m:
            pat=m.group(0)
            # check if file is just repetitions (possibly truncated)
            n=len(data)//len(pat)
            ok = data==pat*n+pat[:len(data)-n*len(pat)]
            if not ok:
                print("ANOMALY:",p,len(data))
        else:
            # non record files: check content classes
            if set(data)=={0x78}:
                pass # x decoy
            elif set(data)=={0}:
                pass # zero decoy
            else:
                print("ODD:",p,len(data),data[:80])
print("done")
EOF

